syntax:
type *ptr = array; // Pointer to array
*(ptr + index) // Access element at position 'index'
// For multi-dimensional arrays: *(base_ptr + row * row_size + col)

code_example:
int mango[3] = {10, 20, 30};
int *p = mango;
printf("%d\n", *(p + 2)); // Accessing mango[2] via pointer arithmetic
int matrix[2][3] = {{1, 2, 3}, {4, 5, 6}};
int *ptr = &matrix[0][0];
printf("%d\n", *(ptr + 4)); // Accessing matrix[1][1] (value 5) via pointer arithmetic
